6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px;\">20</text></g><g class=\"tick y-tick\" opacity=\"1\" transform=\"translate(0,59.196484375000004)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px;\">30</text></g><g class=\"tick y-tick\" opacity=\"1\" transform=\"translate(0,32.72552083333333)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px;\">40</text></g><g class=\"tick y-tick\" opacity=\"1\" transform=\"translate(0,6.254557291666666)\"><line stroke=\"currentColor\" x2=\"6px\" x1=\"-6px\" stroke-width=\"1px\"></line><text fill=\"currentColor\" x=\"-8\" dy=\"0.32em\" style=\"font-family: Noto Serif; font-size: 15px;\">50</text></g><line class=\"y-axis-line\" y1=\"153.109375\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1.5px\"></line><line class=\"y-axis-line\" y1=\"153.109375\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1.5px\" marker-end=\"url(#arrow)\"></line><text class=\"y-axis-label\" style=\"text-anchor: middle; dominant-baseline: text-after-edge; font-family: Noto Serif; font-style: italic; fill: currentColor; font-size: 15px;\" transform=\"translate(0,-12)\">y</text></g><text x=\"0\" y=\"138.109375\" dx=\"-13.25px\" dy=\"13.5px\" fill=\"currentColor\" style=\"font-size: 15px; font-style: italic; font-family: Noto Serif;\">O</text><path d=\"M0,45.461L119.119,138.109\" stroke=\"black\" stroke-width=\"2px\" fill=\"none\" stroke-dasharray=\"none\"></path></g><g class=\"xtitle-group\" transform=\"translate(267.2734375, 194.109375)\"><text class=\"xtitle-group-line-0\" transform=\"translate(0, 0)\" fill=\"currentColor\" style=\"font-family: Noto Serif; font-size: 15px; text-anchor: middle; dominant-baseline: hanging;\">Number of T-shirts</text></g><g class=\"ytitle-group\" transform=\"translate(81.609375, 94.0546875)\"><text class=\"ytitle-group-line-0\" transform=\"translate(0, 0)\" fill=\"currentColor\" style=\"font-family: Noto Serif; font-size: 15px; text-anchor: middle; dominant-baseline: text-before-edge;\">Number of sweatshirts</text></g></svg><div role=\"region\" aria-label=\"Long description for graph of a line\" class=\"sr-only\"><ul>\n<li>The line slants gradually down from left to right.</li>\n<li>The line passes through the following points:<br/>\n<ul>\n<li>(0 comma 35)</li>\n<li>(90 comma 0)</li>\n</ul>\n</li>\n</ul></div></figure></p>\n<p style=\"text-align: left;\">The graph models the relationship between the number of T-shirts, <math alttext=\"x\"><mi>x</mi>\n</math>, and the number of sweatshirts, <math alttext=\"y\"><mi>y</mi>\n</math>, that Kira can purchase for a school fundraiser. Which equation could represent this relationship?</p>","answerOptions":[{"id":"11f3a227-3db6-4811-b615-098d5f3d8680","content":"<p><math alttext=\"y equals 7 x plus 18\"><mrow>\n\t<mi>y</mi>\n\t<mo>=</mo>\n\t<mrow>\n\t\t<mrow>\n\t\t\t<mn>7</mn>\n\t\t\t<mi>x</mi>\n\t\t</mrow>\n\t\t<mo>+</mo>\n\t\t<mn>18</mn>\n\t</mrow>\n</mrow>\n</math></p>"},{"id":"70d63459-54ec-45c4-977d-8612198afb19","content":"<p><math alttext=\"7 x plus 18 y equals 630\"><mrow>\n\t<mrow>\n\t\t<mrow>\n\t\t\t<mn>7</mn>\n\t\t\t<mi>x</mi>\n\t\t</mrow>\n\t\t<mo>+</mo>\n\t\t<mrow>\n\t\t\t<mn>18</mn>\n\t\t\t<mi>y</mi>\n\t\t</mrow>\n\t</mrow>\n\t<mo>=</mo>\n\t<mn>630</mn>\n</mrow>\n</math></p>"},{"id":"9b228f6e-23d3-44ba-9754-9e6e2402c643","content":"<p><math alttext=\"y equals 18 x plus 7\"><mrow>\n\t<mi>y</mi>\n\t<mo>=</mo>\n\t<mrow>\n\t\t<mrow>\n\t\t\t<mn>18</mn>\n\t\t\t<mi>x</mi>\n\t\t</mrow>\n\t\t<mo>+</mo>\n\t\t<mn>7</mn>\n\t</mrow>\n</mrow>\n</math></p>"},{"id":"28c92c61-9616-4394-8e3d-4d0a7511fa4a","content":"<p><math alttext=\"18 x plus 7 y equals 630\"><mrow>\n\t<mrow>\n\t\t<mrow>\n\t\t\t<mn>18</mn>\n\t\t\t<mi>x</mi>\n\t\t</mrow>\n\t\t<mo>+</mo>\n\t\t<mrow>\n\t\t\t<mn>7</mn>\n\t\t\t<mi>y</mi>\n\t\t</mrow>\n\t</mrow>\n\t<mo>=</mo>\n\t<mn>630</mn>\n</mrow>\n</math></p>"}],"keys":["70d63459-54ec-45c4-977d-8612198afb19"],"correct_answer":["B"],"rationale":"<p style=\"text-align: left;\">Choice B is correct. A line in the <em>x</em><em>y</em>-plane can be written as <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y equals m x plus b\"><mi>y</mi><mo>=</mo><mi>m</mi><mi>x</mi><mo>+</mo><mi>b</mi></math>, where <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"m\"><mi>m</mi></math> is the slope of the line and <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"b\"><mi>b</mi></math> is the <em>y</em>-coordinate of the <em>y</em>-intercept. The graph shown is a line passing through the points <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 0 comma 35 right parenthesis\"><mo>(</mo><mn>0</mn><mo>,</mo><mn>35</mn><mo>)</mo></math> and <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 90 comma 0 right parenthesis\"><mo>(</mo><mn>90</mn><mo>,</mo><mn>0</mn><mo>)</mo></math>. Substituting <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"0\"><mn>0</mn></math> for <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"x\"><mi>x</mi></math> and <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"35\"><mn>35</mn></math> for <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y\"><mi>y</mi></math> in the equation <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y equals m x plus b\"><mi>y</mi><mo>=</mo><mi>m</mi><mi>x</mi><mo>+</mo><mi>b</mi></math> yields <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"35 equals m left parenthesis 0 right parenthesis plus b\"><mn>35</mn><mo>=</mo><mi>m</mi><mo>(</mo><mn>0</mn><mo>)</mo><mo>+</mo><mi>b</mi></math>, or <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"35 equals b\"><mn>35</mn><mo>=</mo><mi>b</mi></math>. Substituting <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"35\"><mn>35</mn></math> for <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"b\"><mi>b</mi></math>, <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"90\"><mn>90</mn></math> for <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"x\"><mi>x</mi></math>, and <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"0\"><mn>0</mn></math> for <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y\"><mi>y</mi></math> in the equation <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y equals m x plus b\"><mi>y</mi><mo>=</mo><mi>m</mi><mi>x</mi><mo>+</mo><mi>b</mi></math> yields <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"0 equals 90 m plus 35\"><mn>0</mn><mo>=</mo><mn>90</mn><mi>m</mi><mo>+</mo><mn>35</mn></math>. Subtracting <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"35\"><mn>35</mn></math> from both sides of this equation yields <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"negative 35 equals 90 m\"><mo>-</mo><mn>35</mn><mo>=</mo><mn>90</mn><mi>m</mi></math>. Dividing both sides of this equation by <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"90\"><mn>90</mn></math> yields <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"negative StartFraction 35 Over 90 EndFraction equals m\"><mo>-</mo><mfrac><mn>35</mn><mn>90</mn></mfrac><mo>=</mo><mi>m</mi></math>, or <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"negative seven eighteenths equals m\"><mo>-</mo><mfrac><mn>7</mn><mn>18</mn></mfrac><mo>=</mo><mi>m</mi></math>. Substituting <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"negative seven eighteenths\"><mo>-</mo><mfrac><mn>7</mn><mn>18</mn></mfrac></math> for <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"m\"><mi>m</mi></math> and <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"35\"><mn>35</mn></math> for <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"b\"><mi>b</mi></math> in the equation <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y equals m x plus b\"><mi>y</mi><mo>=</mo><mi>m</mi><mi>x</mi><mo>+</mo><mi>b</mi></math> yields <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y equals minus seven eighteenths x plus 35\"><mi>y</mi><mo>=</mo><mo>-</mo><mfrac><mn>7</mn><mn>18</mn></mfrac><mi>x</mi><mo>+</mo><mn>35</mn></math>. Multiplying both sides of this equation by <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"18\"><mn>18</mn></math> yields <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"18 y equals minus 7 x plus 35 left parenthesis 18 right parenthesis\"><mn>18</mn><mi>y</mi><mo>=</mo><mo>-</mo><mn>7</mn><mi>x</mi><mo>+</mo><mn>35</mn><mo>(</mo><mn>18</mn><mo>)</mo></math>, or <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"18 y equals minus 7 x plus 630\"><mn>18</mn><mi>y</mi><mo>=</mo><mo>-</mo><mn>7</mn><mi>x</mi><mo>+</mo><mn>630</mn></math>. Adding <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"7 x\"><mn>7</mn><mi>x</mi></math> to both sides of this equation yields <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"7 x plus 18 y equals 630\"><mn>7</mn><mi>x</mi><mo>+</mo><mn>18</mn><mi>y</mi><mo>=</mo><mn>630</mn></math>. Therefore, the equation <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"7 x plus 18 y equals 630\"><mn>7</mn><mi>x</mi><mo>+</mo><mn>18</mn><mi>y</mi><mo>=</mo><mn>630</mn></math> represents the relationship between <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"x\"><mi>x</mi></math> and <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"y\"><mi>y</mi></math> modeled by the graph.</p>\n<p style=\"text-align: left;\">Choice A is incorrect. The point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 0 comma 35 right parenthesis\"><mo>(</mo><mn>0</mn><mo>,</mo><mn>35</mn><mo>)</mo></math> is not on the graph of this equation, since <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"7 left parenthesis 0 right parenthesis plus 18 equals 18\"><mn>7</mn><mo>(</mo><mn>0</mn><mo>)</mo><mo>+</mo><mn>18</mn><mo>=</mo><mn>18</mn></math>, not <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"35\"><mn>35</mn></math>.</p>\n<p style=\"text-align: left;\">Choice C is incorrect. The point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 0 comma 35 right parenthesis\"><mo>(</mo><mn>0</mn><mo>,</mo><mn>35</mn><mo>)</mo></math> is not on the graph of this equation, since <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"18 left parenthesis 0 right parenthesis plus 7 equals 7\"><mn>18</mn><mo>(</mo><mn>0</mn><mo>)</mo><mo>+</mo><mn>7</mn><mo>=</mo><mn>7</mn></math>, not <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"35\"><mn>35</mn></math>.</p>\n<p style=\"text-align: left;\">Choice D is incorrect. The point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 90 comma 0 right parenthesis\"><mo>(</mo><mn>90</mn><mo>,</mo><mn>0</mn><mo>)</mo></math> is not on the graph of this equation, since <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"18 left parenthesis 90 right parenthesis plus 7 left parenthesis 0 right parenthesis equals 1,620\"><mn>18</mn><mo>(</mo><mn>90</mn><mo>)</mo><mo>+</mo><mn>7</mn><mo>(</mo><mn>0</mn><mo>)</mo><mo>=</mo><mn>1,620</mn></math>, not <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"630\"><mn>630</mn></math>.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"image_count":0,"raw_list":{"updateDate":1755117017719,"pPcc":"SAT#H","questionId":"00b9bd37","skill_cd":"H.C.","score_band_range_cd":4,"skill_desc":"Linear equations in two variables","createDate":1755117017719,"program":"SAT","primary_c